"""Exact proof of favorite attachment with two exceptional double recipients.

Standard-library checker; the producing solvers are never imported. The proof
method and Boolean/Farkas/RUP primitives follow Aster's protected_linear_certificate
contribution. This module reconstructs a different, complete owner-side problem.
See TWO_EXCEPTIONAL_CERTIFICATE.md for the theorem and its precise limits.
"""
from __future__ import annotations

import argparse
import base64
from collections import deque
from fractions import Fraction
from functools import lru_cache
from itertools import combinations
import json
from math import gcd
from pathlib import Path
import zlib


@lru_cache(maxsize=1)
def graph():
    """Every allocation of sizes (2,2,2,1,1) with good 0 fixed on agent 3."""
    states = []
    for singleton in range(1, 8):
        pool = set(range(1, 8)) - {singleton}
        for first in combinations(sorted(pool), 2):
            for second in combinations(sorted(pool - set(first)), 2):
                owners = [2] * 8
                owners[0], owners[singleton] = 3, 4
                for g in first:
                    owners[g] = 0
                for g in second:
                    owners[g] = 1
                states.append(tuple(owners))
    states = tuple(sorted(states))
    index = {state: k for k, state in enumerate(states)}
    edges = []
    for k, state in enumerate(states):
        for g, h in combinations(range(1, 8), 2):
            if state[g] == state[h]:
                continue
            changed = list(state)
            changed[g], changed[h] = changed[h], changed[g]
            other = index[tuple(changed)]
            if other < k:
                edges.append((other, k))
    return states, tuple(edges)


def need(condition, message):
    if not condition:
        raise ValueError(message)


def literal(value, size):
    need(type(value) is int and 0 < abs(value) <= size, "invalid propositional literal")
    return value


class Formulas:
    """Acyclic Boolean definitions and independently rebuilt mathematical premises."""

    def __init__(self, variables, states, edges, case):
        self.variables = variables
        self.size = len(variables)
        self.atoms, self.names, self.ops, self.defs = {}, {}, {}, {}
        self.clauses = [(1,)]
        need(variables and variables[0] == ["true"], "variable one must be true")
        for k, spec in enumerate(variables[1:], 2):
            need(isinstance(spec, list) and spec, "invalid variable definition")
            kind = spec[0]
            if kind == "linear":
                need(len(spec) == 3 and type(spec[1]) is int and spec[1] in (0, 1, 4), "invalid utility row")
                c = spec[2]
                need(len(c) == 8 and all(type(v) is int for v in c) and any(c) and c[0] == 0, "invalid linear form")
                need(gcd(*c) == 1, "linear form is not primitive")
                key = spec[1], tuple(c)
                need(key not in self.atoms, "duplicate linear atom")
                self.atoms[key] = k
            elif kind in ("fair", "reach"):
                need(len(spec) == 2 and type(spec[1]) is int and spec[1] in range(len(states)), "invalid vertex variable")
                need(tuple(spec) not in self.names, "duplicate vertex variable")
                self.names[tuple(spec)] = k
            else:
                need(kind in ("and", "or", "iff") and len(spec) == 2, "unknown Boolean definition")
                args = tuple(literal(v, k - 1) for v in spec[1])
                need(len(args) >= 2 and (kind != "iff" or len(args) == 2), "invalid Boolean arity")
                key = kind, args
                need(key not in self.ops, "duplicate Boolean definition")
                self.ops[key], self.defs[k] = k, key
                if kind == "and":
                    self.clauses.extend((-k, v) for v in args)
                    self.clauses.append((k,) + tuple(-v for v in args))
                elif kind == "or":
                    self.clauses.extend((k, -v) for v in args)
                    self.clauses.append((-k,) + args)
                else:
                    a, b = args
                    self.clauses.extend(((-k, -a, b), (-k, a, -b), (k, a, b), (k, -a, -b)))
        self._premises(states, edges, case)

    def combine(self, kind, args):
        args = tuple(args)
        if kind == "iff":
            a, b = args
            if a == b:
                return 1
            if a == -b:
                return -1
            args = tuple(sorted(args))
        else:
            args = set(args)
            if (kind == "and" and -1 in args) or (kind == "or" and 1 in args):
                return -1 if kind == "and" else 1
            args.discard(1 if kind == "and" else -1)
            if any(-a in args for a in args):
                return -1 if kind == "and" else 1
            args = tuple(sorted(args))
            if not args:
                return 1 if kind == "and" else -1
            if len(args) == 1:
                return args[0]
        need((kind, args) in self.ops, "missing definition of a mathematical premise")
        return self.ops[kind, args]

    def comparison(self, row, owned, good):
        c = tuple(owned.count(g) - int(g == good) for g in range(8))
        if not any(c):
            return 1
        divisor = gcd(*c)
        key = row, tuple(v // divisor for v in c)
        need(key in self.atoms, "missing utility comparison")
        return self.atoms[key]

    def _premises(self, states, edges, case):
        def require(value):
            self.clauses.append((value,))
        for i in (0, 1, 4):
            for g in range(1, 8):
                require(self.comparison(i, [g], -1))
        for g in range(2, 8):
            require(self.comparison(4, [1], g))
        for k, state in enumerate(states):
            clauses = []
            for i in (0, 1, 4):
                own = [g for g in range(1, 8) if state[g] == i]
                for j in range(3):
                    if i != j:
                        clauses.append(self.combine("or", (self.comparison(i, own, g)
                            for g in range(1, 8) if state[g] == j)))
            require(self.combine("iff", (self.names["fair", k],
                                          self.combine("and", clauses))))
        for a, b in edges:
            same = self.combine("iff", (self.names["reach", a], self.names["reach", b]))
            require(self.combine("or", (-self.names["fair", a],
                                         -self.names["fair", b], same)))
        start = (3, 0, 0, 1, 1, 2, 2, 4) if case == "exceptional" else (3, 2, 0, 0, 1, 1, 2, 4)
        root = states.index(start)
        require(self.names["fair", root])
        require(self.names["reach", root])
        for k, state in enumerate(states):
            if state[1] == 4:
                require(self.combine("or", (-self.names["fair", k],
                                             -self.names["reach", k])))


class BooleanDiagrams:
    """Reduced ordered decision diagrams certify Boolean tautologies exactly."""

    def __init__(self, definitions):
        self.definitions = definitions
        self.nodes, self.unique, self.values = [None, None], {}, {}
        self.negated, self.applied = {0: 1, 1: 0}, {}

    def node(self, v, low, high):
        if low == high:
            return low
        key = v, low, high
        if key not in self.unique:
            self.unique[key] = len(self.nodes)
            self.nodes.append(key)
        return self.unique[key]

    def negate(self, a):
        if a not in self.negated:
            v, low, high = self.nodes[a]
            self.negated[a] = self.node(v, self.negate(low), self.negate(high))
        return self.negated[a]

    def apply(self, op, a, b):
        a, b = sorted((a, b))
        key = op, a, b
        if key in self.applied:
            return self.applied[key]
        if op == "and" and a == 0:
            result = 0
        elif op == "or" and (a == 1 or b == 1):
            result = 1
        elif a == b:
            result = a
        elif (op == "and" and a == 1) or (op == "or" and a == 0):
            result = b
        else:
            av, al, ah = self.nodes[a]
            bv, bl, bh = self.nodes[b]
            v = min(av, bv)
            al, ah = (al, ah) if av == v else (a, a)
            bl, bh = (bl, bh) if bv == v else (b, b)
            result = self.node(v, self.apply(op, al, bl), self.apply(op, ah, bh))
        self.applied[key] = result
        return result

    def value(self, lit):
        if lit < 0:
            return self.negate(self.value(-lit))
        if lit == 1:
            return 1
        if lit not in self.values:
            if lit not in self.definitions:
                result = self.node(lit, 0, 1)
            else:
                op, args = self.definitions[lit]
                xs = [self.value(v) for v in args]
                if op == "iff":
                    a, b = xs
                    result = self.apply("or", self.apply("and", a, b),
                                        self.apply("and", self.negate(a), self.negate(b)))
                else:
                    result = 1 if op == "and" else 0
                    for v in xs:
                        result = self.apply(op, result, v)
            self.values[lit] = result
        return self.values[lit]

    def tautology(self, clause):
        result = 0
        for v in clause:
            result = self.apply("or", result, self.value(v))
        return result == 1


class Propagation:
    """Two watched literals implement reverse unit propagation (RUP)."""

    def __init__(self):
        self.clauses, self.positions, self.units, self.watch = [], [], [], {}
        self.empty = False

    def add(self, clause):
        clause = tuple(sorted(set(clause)))
        if any(-v in clause for v in clause):
            return
        k = len(self.clauses)
        self.clauses.append(clause)
        if not clause:
            self.empty = True
        if len(clause) < 2:
            self.units.extend(clause)
            self.positions.append(None)
        else:
            self.positions.append([0, 1])
            for v in clause[:2]:
                self.watch.setdefault(v, set()).add(k)

    def contradiction(self, assumed_clause):
        if self.empty:
            return True
        assigned = set()
        queue = self.units + [-v for v in assumed_clause]
        while queue:
            v = queue.pop()
            if v in assigned:
                continue
            if -v in assigned:
                return True
            assigned.add(v)
            for k in list(self.watch.get(-v, ())):
                clause, positions = self.clauses[k], self.positions[k]
                slot = 0 if clause[positions[0]] == -v else 1
                other = clause[positions[1 - slot]]
                if other in assigned:
                    continue
                replacement = next((j for j, x in enumerate(clause)
                                    if j not in positions and -x not in assigned), None)
                if replacement is not None:
                    self.watch[-v].remove(k)
                    self.watch.setdefault(clause[replacement], set()).add(k)
                    positions[slot] = replacement
                elif -other in assigned:
                    return True
                else:
                    queue.append(other)
        return False

def verify_certificate(data):
    """Refute a fair cut between the selected start and every favorite state."""
    need(data.get("format") == "two-exceptional-attachment-rup-v1", "unknown proof format")
    case = data.get("case")
    need(case in ("exceptional", "automatic"), "unknown donor case")
    states, edges = graph()
    formulas = Formulas(data["variables"], states, edges, case)
    propagation = Propagation()
    for clause in formulas.clauses:
        propagation.add(clause)
    def checked_clause(clause):
        need(isinstance(clause, list), "proof clauses must be lists")
        return tuple(literal(v, formulas.size) for v in clause)
    for clause, weights in data["theory"]:
        clause = checked_clause(clause)
        need(all(abs(v) in {value for value in formulas.atoms.values()} for v in clause), "nonlinear theory clause")
        total = [[Fraction(0) for _ in range(8)] for _ in range(5)]
        strict = False
        for index, numerator, denominator in weights:
            need(type(index) is int and index in range(len(clause)) and type(numerator) is int
                 and type(denominator) is int and numerator > 0 and denominator > 0, "invalid positive multiplier")
            v = clause[index]
            _, row, coefficients = formulas.variables[abs(v) - 1]
            factor = Fraction(numerator, denominator) * (-1 if v > 0 else 1)
            for g, coefficient in enumerate(coefficients):
                total[row][g] += factor * coefficient
            strict |= v > 0
        need(strict and not any(value for row in total for value in row), "linear contradiction does not sum to zero")
        propagation.add(clause)
    diagrams = BooleanDiagrams(formulas.defs)
    for clause in data["tautologies"]:
        clause = checked_clause(clause)
        need(diagrams.tautology(clause), "claimed Boolean tautology is false")
        propagation.add(clause)
    proof = data["proof"]
    need(proof and proof[-1] == [], "proof must conclude with the empty clause")
    for k, clause in enumerate(proof):
        clause = checked_clause(clause)
        need(propagation.contradiction(clause), f"RUP step {k} is not justified")
        propagation.add(clause)
    return {"case": case, "vertices": len(states), "edges": len(edges), "variables": formulas.size,
            "linear_lemmas": len(data["theory"]), "Boolean_lemmas": len(data["tautologies"]),
            "RUP_steps": len(proof)}


@lru_cache(maxsize=1)
def certificates():
    """Decode proof data. No hash or producer assertion grants acceptance."""
    return json.loads(zlib.decompress(base64.b85decode(_PROOF)))


@lru_cache(maxsize=1)
def verified_proof():
    return tuple(verify_certificates(certificates()))


def verify_certificates(data):
    """Verify exactly one proof for each of the two donor cases."""
    need(isinstance(data, list) and len(data) == 2,
         "proof pair must contain exactly two proof objects")
    need(all(isinstance(item, dict) for item in data),
         "proof pair entries must be objects")
    need([item.get("case") for item in data] in (
        ["exceptional", "automatic"], ["automatic", "exceptional"]),
        "proof pair must contain each donor case exactly once")
    return [verify_certificate(item) for item in data]


def _fair(utilities, state):
    for i, row in enumerate(utilities):
        own = sum(row[g] for g, owner in enumerate(state) if owner == i)
        for j in range(3):
            pair = [g for g, owner in enumerate(state) if owner == j]
            if own < min(row[g] for g in pair):
                return False
    return True


def favorite_attachment(utilities, start):
    """Return a fair path to agent 4's favorite, with good 0 fixed on agent 3.

    Canonical agent roles are exceptional 0,1; automatic 2; singleton 3,4.
    Input values may be exact integers or Fractions. The theorem permits reals.
    """
    need(len(utilities) == 5 and all(len(row) == 8 for row in utilities),
         "need five utility rows on eight goods")
    need(all(type(v) in (int, Fraction) and v >= 0 for row in utilities for v in row),
         "utilities must be exact nonnegative integers or Fractions")
    states, edges = graph()
    start = tuple(start)
    need(start in states, "need sizes (2,2,2,1,1) and good zero on agent three")
    need(all(row[0] == max(row) for row in utilities[3:]),
         "protected good must be a shared favorite")
    automatic = sorted(utilities[2][1:])
    need(automatic[0] + automatic[1] >= automatic[-2],
         "third double recipient must be automatically fair")
    need(_fair(utilities, start), "start must be EF1")
    verified_proof()
    active_good = start.index(4)
    best_good = max(range(1, 8), key=lambda g: (utilities[4][g], -g))
    if active_good == best_good:
        return [start]
    # Search the complete graph, whose existence guarantee is the checked proof.
    index = {state: k for k, state in enumerate(states)}
    adjacency = [[] for _ in states]
    for a, b in edges:
        adjacency[a].append(b)
        adjacency[b].append(a)
    root = index[start]
    previous = {root: None}
    queue = deque([root])
    while queue:
        k = queue.popleft()
        if states[k].index(4) == best_good:
            route = [k]
            while previous[route[-1]] is not None:
                route.append(previous[route[-1]])
            return [states[j] for j in reversed(route)]
        for other in adjacency[k]:
            if other not in previous and _fair(utilities, states[other]):
                previous[other] = k
                queue.append(other)
    raise AssertionError("checked attachment theorem contradicted")


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--export", type=Path, help="export the full readable JSON proof")
    parser.add_argument("--certificate", type=Path, help="check a supplied JSON proof pair")
    args = parser.parse_args()
    try:
        data = json.loads(args.certificate.read_text()) if args.certificate else certificates()
        reports = verify_certificates(data)
        if args.export:
            args.export.write_text(json.dumps(data, separators=(",", ":")) + "\n")
    except (OSError, ValueError, KeyError, TypeError, IndexError) as error:
        parser.exit(2, f"certificate error: {error}\n")
    print(json.dumps({"status": "verified", "proofs": reports}, indent=2))


